import{fB as o,fA as a,fC as r,fz as s}from"./index-B1DfYRMv.js";import{S as e}from"./shared-Crjz4w_p.js";const n={"prod-n1-l01":o(a("La producción musical es el proceso de convertir una idea en una canción terminada: componer o arreglar, grabar, editar, mezclar y entregar el audio final.","Hoy gran parte de ese trabajo se hace en una computadora con un DAW (estación de trabajo de audio digital): el programa donde se graban, se acomodan y se mezclan los sonidos.","> Escucha una canción que te guste y piensa: ¿qué instrumentos tiene?, ¿qué suena primero?"),a("Existen muchos DAW, gratuitos y de pago (por ejemplo GarageBand, BandLab, Reaper, FL Studio, Ableton Live o Logic Pro). Tu maestro te dirá cuál usar en clase.","Al abrirlo, ubica sus partes principales: la línea de tiempo (donde se acomodan las pistas), las pistas, los controles de transporte (reproducir, detener, grabar), el metrónomo y el mezclador.","> Explora sin miedo: siempre puedes deshacer con Ctrl+Z (o Cmd+Z)."),a("La línea de tiempo del DAW se divide en compases y tiempos, igual que una partitura. Arriba verás una regla con números: 1, 2, 3… son los compases.","Muchos DAW muestran la posición como compás.tiempo (por ejemplo, 5.3 = compás 5, tiempo 3).","> Mueve el cursor de reproducción al compás 9 y dale play."),a("Escucha una canción y trata de reconocer los instrumentos: batería, bajo, guitarras o teclados, voz…","Cada uno ocupa su propio espacio: unos graves, otros agudos; unos marcan el ritmo y otros la melodía.","> Haz una lista de todos los instrumentos que escuches en una canción.")),"prod-n1-l02":o(a('Todo sonido tiene cuatro propiedades: altura (agudo o grave), duración (largo o corto), intensidad (fuerte o suave) y timbre (el "color" de cada sonido).',"En producción trabajas con las cuatro: eliges las notas, editas cuánto duran, ajustas el volumen de cada pista y escoges los sonidos (el timbre).","> Abre un instrumento en tu DAW y escucha la misma nota con tres sonidos diferentes."),a("Al crear un proyecto nuevo, define primero el tempo (en BPM) y el compás (por ejemplo, 4/4). Así la cuadrícula y el metrónomo coinciden con tu música.","Ponle nombre al proyecto y guárdalo en una carpeta ordenada desde el principio.","> Guarda tu proyecto seguido (Ctrl+S / Cmd+S)."),r("n1-l02","lectura"),a("Activa el metrónomo de tu DAW y aplaude junto con el clic. Después escucha una canción e intenta encontrar su pulso con el pie.",'> Prueba la herramienta de "tap tempo" si tu DAW la tiene: tocas al ritmo y te dice los BPM.')),"prod-n1-l03":o(a("El audio es sonido grabado (por ejemplo, una voz con micrófono). Se ve como una forma de onda.","El MIDI no es sonido: son instrucciones (qué nota, cuándo empieza, cuánto dura y con qué fuerza). Un instrumento virtual convierte esas instrucciones en sonido.","> Ventaja del MIDI: puedes cambiar notas y sonidos después de grabar."),a("Graba notas MIDI con un teclado controlador o dibújalas con el ratón en el editor de notas.","Si grabas tocando, activa el metrónomo y usa la cuantización con cuidado: acomoda las notas a la cuadrícula.","> Prueba dibujar una escala de Do mayor con el ratón."),a("El editor de notas (piano roll) muestra un teclado vertical a la izquierda (altura) y la cuadrícula del tiempo de izquierda a derecha (duración).","Cada rectángulo es una nota: su posición vertical es la altura, su largo es la duración y su color o barra inferior suele indicar la intensidad (velocity).","> Alarga y acorta una nota para escuchar el cambio."),a("La altura nos dice si un sonido es agudo o grave. En el editor de notas, mientras más arriba esté una nota, más aguda suena.","> Dibuja una nota muy arriba y otra muy abajo y compáralas.")),"prod-n1-l04":o(a("Las figuras rítmicas indican duración: en 4/4, la negra dura 1 tiempo, la corchea medio tiempo y la semicorchea un cuarto de tiempo.",'La subdivisión es dividir el pulso en partes más pequeñas: "1 y 2 y" (corcheas) o "1 e y a" (semicorcheas).',"> En el DAW, cambia la cuadrícula a 1/8 y luego a 1/16 para ver la diferencia."),a("Un ritmo básico de batería en 4/4: bombo en los tiempos 1 y 3, tarola en los tiempos 2 y 4, y hi-hat (platillo) en corcheas.","Prográmalo en un instrumento de batería del DAW, repítelo 4 compases y escúchalo en loop.",'> Después mueve un bombo a la "y" del tiempo 2 o 3 y escucha cómo cambia la sensación.'),a("En la cuadrícula, cada compás de 4/4 tiene 4 negras, 8 corcheas o 16 semicorcheas.","Las líneas más marcadas indican el inicio de cada tiempo.","> Cuenta los cuadros de un compás con la cuadrícula en 1/16."),a('El bombo suena grave, la tarola seca y aguda, y el hi-hat como un "tss" corto. El contratiempo es lo que cae entre los tiempos (en la "y").','> Escucha una canción y di "bum" en cada bombo, "pa" en cada tarola y "ts" en cada hi-hat.')),"prod-n1-l05":o(a("Las notas musicales son siete: Do, Re, Mi, Fa, Sol, La y Si. Con las teclas negras hay 12 sonidos diferentes en cada octava.","El semitono es la distancia entre dos teclas vecinas; el tono equivale a dos semitonos. Entre Mi-Fa y Si-Do solo hay un semitono.","> En el editor de notas, cada fila es un semitono."),a("La línea de bajo suele tocar la nota principal (fundamental) de cada acorde, en registro grave.","Empieza con notas largas (una por compás) y después prueba ritmos que coincidan con el bombo.","> Usa un sonido de bajo y escribe Do, La, Fa y Sol, un compás cada uno."),a("En el editor de notas, el teclado de la izquierda muestra el nombre de las teclas (normalmente en cifrado: C, D, E…) y el número de octava (C3, C4…).","Cuidado: algunos DAW llaman C3 al Do central y otros C4.","> Encuentra el Do central en tu DAW y anota cómo lo nombra."),a('Un semitono suena muy "pegadito" y tenso; un tono suena un poco más abierto.',"> Dibuja Mi-Fa y luego Do-Re y compáralos.")),"prod-n1-l06":o(a("Un acorde son tres o más notas sonando juntas. El acorde mayor se forma con la fundamental, la nota 4 semitonos arriba y la nota 7 semitonos arriba (Do-Mi-Sol).","El acorde menor usa la fundamental, 3 semitonos arriba y 7 semitonos arriba (La-Do-Mi).","> Mayor = 4 + 3 semitonos. Menor = 3 + 4 semitonos."),a("Programa una progresión de 4 acordes, uno por compás, por ejemplo: C - G - Am - F.","Usa un sonido de piano o pad y escúchala en loop.","> Prueba el mismo ciclo en otro orden: Am - F - C - G."),r("n1-l08","teoria"),a("Los acordes mayores suenan brillantes y alegres; los menores, más oscuros o melancólicos.","> Escucha C y luego Am. ¿Cuál te suena más alegre?")),"prod-n1-l07":o(a("Una escala es una serie ordenada de notas. La escala de Do mayor usa solo las teclas blancas: Do, Re, Mi, Fa, Sol, La, Si.",'La tonalidad es la escala "base" de una canción. La tónica es la nota principal, donde la música se siente en casa.',"> En Do mayor, la tónica es Do."),a("Crea una melodía sobre tu progresión usando notas de la escala de Do mayor.","Un buen truco: en el primer tiempo de cada acorde, usa una nota que pertenezca a ese acorde.","> Canta o tararea tu idea antes de escribirla: las melodías que se pueden cantar se recuerdan mejor."),a("En el editor de notas, la escala mayor tiene un patrón de distancias: tono-tono-semitono-tono-tono-tono-semitono.","Algunos DAW pueden resaltar las notas de la escala para ayudarte.","> Dibuja la escala de Do mayor y cuenta las filas entre cada nota."),a('La tónica es la nota donde la melodía "descansa". Al final de muchas canciones, la melodía termina en la tónica.',"> Toca una escala y detente en Si: ¿sientes que le falta algo? Toca Do y escucha cómo se resuelve.")),"prod-n1-l08":o(a("Los instrumentos virtuales (plugins) generan sonido a partir de MIDI. Algunos usan grabaciones reales (samplers) y otros crean el sonido electrónicamente (sintetizadores).","Los efectos (como reverberación o eco) transforman el sonido de una pista.","> Prueba el mismo patrón con un piano, un sintetizador y unas cuerdas."),a("Elige un sonido para cada pista: batería, bajo, acordes y melodía.","Busca que no compitan entre sí: si todo es muy grave o todo muy agudo, la mezcla se vuelve confusa.","> Ponle nombre y color a cada pista para no perderte."),a("Los controles comunes de un instrumento virtual: volumen, paneo (izquierda-derecha), selección de sonido (preset) y, en sintetizadores, filtro y envolvente (ataque y decaimiento del sonido).","> Mueve un control a la vez y escucha qué cambia."),a("Cada instrumento tiene su timbre: el piano tiene un ataque claro, las cuerdas entran más suaves, el sintetizador puede sonar de muchas formas y el bajo ocupa la zona grave.","> Escucha una canción e identifica estos instrumentos.")),"prod-n1-l09":o(a("Para grabar audio necesitas: un micrófono, una interfaz de audio (que convierte el sonido en datos para la computadora), cables y audífonos.","Hay micrófonos dinámicos (resistentes, buenos para voces fuertes e instrumentos) y de condensador (más sensibles, muy usados en estudio; necesitan alimentación fantasma de +48 V).","> Usa audífonos al grabar para que el micrófono no capte la pista."),a("Graba una voz o un instrumento en una pista de audio. Antes de grabar, ajusta la ganancia en la interfaz.","Graba varias tomas y quédate con la mejor.","> Busca un lugar silencioso y aleja el micrófono de ventiladores y ventanas."),a("El medidor de nivel muestra qué tan fuerte llega la señal. Si llega a 0 dBFS (la zona roja), el audio se satura y suena distorsionado.","Un rango de referencia común al grabar es que los picos queden más o menos entre -12 y -6 dBFS.","> Pide a quien grabas que cante o toque lo más fuerte de la canción mientras ajustas la ganancia."),a('Aprende a reconocer tres problemas: ruido (un "shhh" de fondo), saturación (distorsión en las partes fuertes) y nivel muy bajo (hay que subir mucho el volumen y aparece ruido).',"> Escucha tus grabaciones con audífonos para detectar estos problemas.")),"prod-n1-l10":o(a("Editar es corregir y acomodar lo grabado: cortar partes que sobran, mover tomas, quitar ruidos entre frases y unir las mejores partes de varias tomas.",'Los fundidos (fade in y fade out) evitan "clics" al inicio y al final de cada corte.',"> Edita siempre con una copia de seguridad del proyecto."),a("Practica: corta el silencio antes de la primera nota, mueve una frase que quedó tarde y pon fundidos cortos en cada corte.","Usa el zoom para ver bien la forma de onda.",'> Activa "ajustar a la cuadrícula" para mover partes a tiempo, y desactívalo para ajustes finos.'),a("La forma de onda muestra el volumen del audio en el tiempo: donde es más alta, el sonido es más fuerte; donde es plana, hay silencio.","Los golpes de batería se ven como picos marcados: te ayudan a ver si una toma está a tiempo.","> Compara una toma de voz y una de batería: ¿cómo se ven diferentes?"),a('Escucha si una toma está a tempo con el metrónomo: si va adelantada o atrasada, se siente "fuera de lugar".',"> Reproduce la toma con el metrónomo y fíjate si los golpes coinciden con el clic.")),"prod-n1-l11":o(a("Muchas canciones populares tienen estas partes: introducción, verso, coro, puente y final. El coro suele ser la parte más fuerte y que más se repite.","En producción, cada sección puede cambiar de energía: menos instrumentos en el verso, más en el coro.","> Escribe la estructura de una canción que te guste: intro, verso, coro…"),a("Ordena tu canción en la línea de tiempo: copia y pega tus patrones para armar introducción, verso y coro.",'Para que el coro "explote", agrega o quita elementos (por ejemplo, el hi-hat entra en el coro).',"> Haz que cada sección dure 4 u 8 compases para empezar."),a('Los marcadores (locators) son etiquetas en la línea de tiempo con nombres como "Verso" o "Coro". Te ayudan a ver la forma de la canción.',"> Agrega un marcador al inicio de cada sección."),a("Escucha una canción e identifica el verso, el coro y el puente. El puente suele sonar diferente, como un descanso antes del último coro.","> Anota en qué minuto empieza cada parte.")),"prod-n1-l12":o(a('Exportar (o "bounce") es convertir tu proyecto en un archivo de audio que se puede escuchar en cualquier lugar.',"WAV es un formato sin compresión, con la mejor calidad (archivos grandes). MP3 está comprimido: pesa mucho menos y es práctico para compartir.","> Valores comunes: WAV a 44.1 kHz o 48 kHz y 24 bits; MP3 a 320 kbps."),a("Antes de exportar, revisa que el canal principal (master) no llegue a la zona roja. Marca el inicio y el final de la canción para no cortar el último sonido.","Exporta tu primera canción y escúchala en diferentes lugares: audífonos, bocina del teléfono, coche.","> Guarda también el proyecto: así podrás hacer cambios después."),a("Repaso: abre un proyecto completo y explica cada parte: pistas, instrumentos, patrones, secciones, marcadores y el mezclador.","> Explícale tu proyecto a alguien de tu familia: si lo puedes explicar, lo entiendes."),a("Una canción de referencia es una canción profesional del estilo que buscas. Compárala con la tuya a volumen parecido.","Fíjate en el balance entre instrumentos, en los graves y en los agudos.","> Escucha primero 10 segundos de la referencia y luego 10 de tu canción."))},i={"prod-n3-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El sonido rebota en paredes, piso y techo. En un cuarto vacío y con paredes paralelas aparecen ecos y resonancias que ensucian la grabación. Las superficies blandas (cortinas, sillones, libreros, alfombras) absorben o dispersan el sonido.",'Para grabar en casa buscamos un cuarto "seco" (con poco eco); para escuchar mezclas, que las bocinas estén simétricas y lejos de las esquinas.'],tips:["Aplaude en el centro del cuarto: si escuchas un zumbido metálico (flutter echo), necesitas más absorción."]},practica:{paragraphs:["Elige el cuarto más silencioso, apaga ventiladores y aparatos ruidosos, cuelga cobijas o cortinas gruesas detrás y a los lados del micrófono y pon una alfombra. Coloca el micrófono lejos de las paredes y de las esquinas."],tips:["Un clóset con ropa es una cabina de voz improvisada muy efectiva."]},lectura:{paragraphs:["Un plano de colocación muestra desde arriba dónde va cada micrófono, instrumento, músico y bocina, con distancias y ángulos. Ayuda a repetir la misma configuración en otra sesión."],tips:["Toma una foto de tu configuración antes de desarmarla."]},oido:{paragraphs:['Un cuarto seco suena cercano y directo; uno con eco, lejano y con "cola". Escucha y decide.'],tips:["Fíjate en lo que suena justo después de que termina cada palabra."]}}},"prod-n3-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Dinámico: resistente, poco sensible, ideal para voces fuertes, amplificadores y en vivo. Condensador: sensible y detallado, ideal para voces y acústicas en estudio (necesita phantom +48 V). De cinta: suave y cálido, delicado.","El patrón polar indica desde dónde capta: cardioide (frente), omnidireccional (todo alrededor) y figura 8 (frente y atrás)."],tips:["Para grabar en casa, el cardioide rechaza mejor el ruido del cuarto."]},practica:{paragraphs:["Voz: condensador cardioide a 15–20 cm con filtro antipop, a la altura de la boca. Guitarra acústica: micrófono apuntando al traste 12 a 15–30 cm. Amplificador: dinámico pegado a la rejilla, cerca del centro del cono para más brillo o al borde para un sonido más suave."],tips:["Mueve el micrófono unos centímetros y escucha: cambia mucho el sonido."]},lectura:{paragraphs:["Un patrón polar es un dibujo circular que muestra la sensibilidad del micrófono en cada ángulo. El centro es el micrófono; la línea más alejada indica dónde capta más."],tips:["En el cardioide, la parte de atrás casi no capta: apúntala hacia el ruido."]},oido:{paragraphs:["Cerca del micrófono: más graves (efecto de proximidad), más presencia, menos cuarto. Lejos: más cuarto y menos graves. Escucha y decide."],tips:["Fíjate en los graves y en el eco del cuarto."]}}},"prod-n3-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La ganancia ajusta qué tan fuerte entra la señal a la interfaz. La estructura de nivel (gain staging) es cuidar que la señal tenga un nivel sano en cada paso: ni tan baja que se oiga ruido, ni tan alta que sature.","En digital, apunta a picos de −12 a −6 dBFS al grabar."],tips:["Si el indicador de la interfaz se pone rojo, baja la ganancia."]},practica:{paragraphs:["Ajusta la ganancia de la interfaz con la parte más fuerte de la canción, luego deja el fader de la pista en 0 dB y revisa que cada plugin no suba de más el nivel. Al final, el bus master no debe pasar de 0 dBFS."],tips:["Usa el control de salida de cada plugin para igualar el volumen de entrada y salida."]},lectura:{paragraphs:["El medidor de pico muestra el punto más alto de la señal (para evitar saturar). El RMS (o LUFS) muestra el volumen promedio, más parecido a cómo percibimos el volumen."],tips:["Una señal puede tener picos altos y sonar baja si su RMS es bajo."]},oido:{paragraphs:["Una señal limpia suena clara; una saturada digitalmente suena rota y áspera en las partes fuertes. Escucha y decide."],tips:["La saturación digital no se puede arreglar después: graba con margen."]}}},"prod-n3-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Una batería completa se graba con varios micrófonos: bombo, caja, toms, overheads (encima, para platillos y conjunto) y a veces del cuarto. En casa se puede empezar con dos overheads y un micrófono de bombo, o grabar percusiones menores (shaker, pandero, cajón) con un solo micrófono."],tips:["Afina la batería antes de grabar: la mezcla no lo arregla."]},practica:{paragraphs:["Graba un shaker o pandero con un micrófono a 30–50 cm, o programa una batería con un instrumento virtual variando la velocity para que suene humana."],tips:["Combina percusión real con batería programada: suena más viva."]},lectura:e.s174,oido:e.s175}},"prod-n3-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La edición de voz incluye elegir las mejores tomas, cortar respiraciones fuertes, quitar ruidos, alinear dobles y ajustar el tiempo de algunas sílabas. Se hace antes de mezclar."],tips:["Usa fundidos (fades) cortos en cada corte para evitar clics."]},practica:{paragraphs:["Comping es combinar las mejores partes de varias tomas en una sola. En el DAW graba varias tomas en carriles (takes) y selecciona frase por frase la mejor."],tips:["Escucha cada frase en todas las tomas antes de elegir."]},lectura:{paragraphs:['Una lista de tomas anota qué toma es mejor en cada sección (por ejemplo, "verso 1: toma 3; coro: toma 5, frase 2 de la toma 2").'],tips:["Anota mientras grabas: después no recordarás cuál era la buena."]},oido:{paragraphs:["Escucha dos tomas y decide cuál es mejor por afinación, tiempo y emoción."],tips:["La emoción importa tanto como la precisión."]}}},"prod-n3-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Los DAW permiten corregir afinación (con herramientas tipo Melodyne o Auto-Tune) y tiempo (cuantización de audio o MIDI). Usadas con moderación, mejoran una toma; en exceso, suenan artificiales (aunque a veces se busca ese efecto)."],tips:["Corrige solo lo que distrae, no todo."]},practica:{paragraphs:["Corrige una toma de voz: ajusta solo las notas claramente desafinadas y respeta los deslizamientos naturales. Luego alinea un doble con la voz principal en los inicios y finales de frase."],tips:["Compara con la toma original al final para no perder la naturalidad."]},lectura:{paragraphs:['El editor de afinación muestra cada nota como una "gota" sobre una cuadrícula de notas: la altura indica la afinación y la línea dentro de la gota, el vibrato y los deslizamientos.'],tips:["Mueve la gota al centro de la nota para afinarla."]},oido:{paragraphs:["Una corrección natural no se nota; una exagerada suena robótica. Escucha y decide."],tips:["Fíjate en los cambios entre notas: si son instantáneos, la corrección es fuerte."]}}},"prod-n3-l07":{status:"borrador",generated:!0,sections:{teoria:e.s032,practica:{paragraphs:["Para programar en cualquier tono, piensa en grados (I, IV, V…) en lugar de nombres de acordes. En el piano roll, muchas DAW permiten resaltar la escala para ver qué notas pertenecen al tono."],tips:["Transporta una progresión completa seleccionándola y moviéndola por semitonos."]},lectura:e.s033,oido:e.s034}},"prod-n3-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Los grados numeran los acordes de la escala: en Do mayor, I = C, ii = Dm, iii = Em, IV = F, V = G, vi = Am, vii° = Bdim. Las progresiones más comunes: I–IV–V, I–V–vi–IV, ii–V–I y vi–IV–I–V."],tips:["Aprende las progresiones como grados: te sirven en cualquier tono."]},practica:{paragraphs:["En el piano roll, programa I–IV–V–I en Do (C–F–G–C) y I–V–vi–IV en Sol (G–D–Em–C), cada acorde un compás. Usa inversiones para que las voces se muevan poco."],tips:["Cambia el instrumento virtual y escucha la misma progresión con otro color."]},lectura:e.s061,oido:e.s062}},"prod-n3-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un arreglo para banda reparte funciones: batería (ritmo), bajo (base armónica y ritmo), guitarras (ritmo y armonía), teclados (colchones o acordes) y voz (melodía). Un buen arreglo deja espacio a cada instrumento en frecuencia y en tiempo."],tips:["Si todos tocan todo el tiempo, nada destaca."]},practica:{paragraphs:["Programa o graba una sección de 8 compases con batería, bajo, guitarra y teclado. Haz que el bajo siga al bombo y que guitarra y teclado ocupen registros distintos."],tips:["Quita un instrumento a la vez para escuchar qué aporta."]},lectura:e.s192,oido:{paragraphs:["Escucha una canción e identifica el rol de cada instrumento: ritmo, base, armonía o melodía."],tips:["Concéntrate en un instrumento a la vez."]}}},"prod-n3-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un bus suma varias pistas en un solo canal: por ejemplo, todas las baterías en un bus de batería. Así puedes ajustar su volumen o aplicar efectos a todo el grupo a la vez. Los envíos (sends) mandan una copia de la señal a un bus de efectos (reverb, delay)."],tips:["Organiza tu sesión con buses: batería, bajo, guitarras, teclados, voces."]},practica:{paragraphs:["Crea buses para batería, guitarras y voces; envía cada pista a su bus y ajusta el volumen general con el fader del bus. Crea un bus de reverb y envía varias pistas con distintas cantidades."],tips:["Nombra y colorea cada bus."]},lectura:{paragraphs:['El ruteo muestra a dónde va la señal de cada pista: su salida (a un bus o al master) y sus envíos. En el mezclador se ve en las secciones "Output" y "Sends".'],tips:["Sigue el camino de una pista hasta el master."]},oido:{paragraphs:["Una pista sola suena aislada; en grupo (bus), junto con otras del mismo tipo. Escucha y decide."],tips:["Fíjate cuántas fuentes suenan a la vez."]}}},"prod-n3-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Una referencia es una canción profesional parecida a la tuya que usas para comparar balance, graves, brillo y volumen. La escucha crítica es analizar con atención: qué se oye, dónde está y por qué funciona."],tips:["Iguala el volumen de la referencia y tu mezcla antes de comparar."]},practica:{paragraphs:["Importa una referencia a tu sesión, baja su volumen para igualarlo con tu mezcla y alterna entre ambas. Compara graves, voz, brillo y ancho estéreo."],tips:["Compara secciones equivalentes (coro con coro)."]},lectura:{paragraphs:["Un analizador de espectro muestra la energía en cada frecuencia: graves a la izquierda (20–250 Hz), medios al centro (250 Hz–4 kHz) y agudos a la derecha (4–20 kHz)."],tips:["Úsalo para comparar tu mezcla con la referencia, pero decide con el oído."]},oido:{paragraphs:["Escucha una mezcla y decide si le sobran o faltan graves, medios o agudos."],tips:["Graves: cuerpo y peso; medios: presencia; agudos: brillo y aire."]}}},"prod-n3-l12":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Presentar una producción es mostrar tu trabajo: explica la idea, el estilo, las referencias, el proceso y lo que aprendiste. Lleva la mezcla exportada en buena calidad."],tips:["Prepara una breve explicación de 1 minuto antes de reproducirla."]},practica:{paragraphs:["Exporta tu producción en WAV, prepara una hoja con título, créditos, tempo y tonalidad, y preséntala al grupo o al profe Luis explicando tus decisiones."],tips:["Pide retroalimentación concreta: qué funciona y qué mejorarías."]},lectura:{paragraphs:["Abre una sesión completa e identifica: pistas, buses, envíos, regiones, automatización y marcadores de sección."],tips:["Describe la sesión en voz alta como si se la explicaras a alguien."]},oido:{paragraphs:["Escucha tu proyecto de principio a fin con atención: ¿la voz se entiende?, ¿los graves están equilibrados?, ¿la canción crece?"],tips:["Escucha en distintos sistemas: audífonos, bocinas, celular y auto."]}}},"prod-n4-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El pop busca un gancho pegajoso y una estructura clara (verso, precoro, coro). La producción usa capas, cortes y entradas de instrumentos para que el coro "explote". Voces muy al frente y brillantes.'],tips:["Escucha cómo cambian los instrumentos entre el verso y el coro de un éxito pop."]},practica:{paragraphs:["Para el coro: dobla la voz principal, agrega armonías, suma un colchón o sintetizador, abre el estéreo y aumenta la energía de la batería. Antes del coro, quita elementos para crear contraste."],tips:["El silencio o un corte antes del coro lo hace sonar más grande."]},lectura:{paragraphs:["La forma pop típica: intro – verso – precoro – coro – verso – precoro – coro – puente – coro final. En el DAW se marca con marcadores de sección."],tips:["Anota la duración de cada sección en compases."]},oido:{paragraphs:["Escucha una canción y señala dónde empieza el verso, el precoro y el coro."],tips:["El coro suele tener el título de la canción y más energía."]}}},"prod-n4-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El beat de hip hop se construye con bombo, caja (o palmas), hi-hats y un sample o melodía, a menudo con swing en los hi-hats. El bajo (o 808) sostiene la base. El tempo suele estar entre 80 y 100 BPM (trap: 130–150 con sensación de mitad de tiempo)."],tips:["Escucha productores como J Dilla para sentir el swing."]},practica:{paragraphs:['Programa bombo en 1 y "y" del 3, caja en 2 y 4, hi-hats en corcheas o semicorcheas, y aplica swing del 55–60% al hi-hat. Agrega un bajo siguiendo al bombo.'],tips:["Varía la velocity de los hi-hats para que no suenen mecánicos."]},lectura:{paragraphs:["En una cuadrícula con swing, las notas del contratiempo aparecen ligeramente retrasadas respecto a la línea. El porcentaje de swing indica cuánto se retrasan."],tips:["50% es recto; 66% es swing de tresillo."]},oido:e.s089}},"prod-n4-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["House: unos 120–126 BPM, bombo en cada tiempo (four on the floor), hi-hat abierto en contratiempo, bajo y acordes de piano o sintetizador. Techno: 125–140 BPM, más repetitivo, oscuro y basado en texturas y percusión."],tips:["Escucha cómo los cambios se hacen quitando y agregando elementos cada 8 o 16 compases."]},practica:{paragraphs:["Programa un bombo en cada tiempo, un hi-hat abierto en cada contratiempo, un bajo en contratiempos y un arpegiador sobre un acorde menor. Aplica sidechain al bajo con el bombo."],tips:["Construye 16 compases agregando un elemento cada 4."]},lectura:e.s193,oido:e.s194}},"prod-n4-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Cumbia: 2/4 o 4/4, güira o guacharaca constante, bajo en tiempos 1 y 3 con anticipaciones, acordeón o teclado. Reggaetón: ritmo dembow (bombo en cada tiempo y caja con el patrón tresillo 3+3+2 en semicorcheas), 85–100 BPM. Balada: tempo lento, piano, cuerdas y voz al frente."],tips:["Escucha un ejemplo de cada estilo y fíjate en el patrón del bajo."]},practica:{paragraphs:["Programa 8 compases de cada estilo: cumbia con güira y bajo, reggaetón con dembow y 808, balada con piano y cuerdas. Usa la misma progresión en los tres."],tips:["Cambia solo el ritmo y el tempo: la progresión puede ser la misma."]},lectura:e.s058,oido:e.s169}},"prod-n4-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La producción de rock se basa en una banda tocando: batería real, bajo, guitarras distorsionadas (a menudo dobladas) y voz potente. Se busca energía y sensación de banda en vivo."],tips:["Escucha cómo las guitarras rítmicas suenan a ambos lados del estéreo."]},practica:{paragraphs:["Graba la misma guitarra rítmica dos veces y panea cada toma a un lado (izquierda y derecha). Ajusta la batería para que bombo y caja tengan pegada."],tips:["Las dos tomas deben ser casi idénticas en tiempo, pero no copias: copiarla no da amplitud."]},lectura:{paragraphs:['En el rock son comunes los power chords (C5, G5), que solo tienen fundamental y quinta. Una guía puede indicar "palm mute" (P.M.) y acentos.'],tips:["Un C5 no es ni mayor ni menor: no tiene tercera."]},oido:{paragraphs:["El sonido limpio es claro; el distorsionado, saturado y agresivo. Escucha y decide."],tips:["Fíjate si las notas se sostienen y se vuelven ásperas."]}}},"prod-n4-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La síntesis sustractiva parte de un oscilador con una onda rica en armónicos (diente de sierra, cuadrada) y le resta frecuencias con un filtro (normalmente paso bajo). La envolvente (ADSR: ataque, decaimiento, sostenimiento, liberación) da forma al volumen y al filtro en el tiempo.",'La resonancia del filtro realza la frecuencia de corte y da un carácter "chillón" o "acuoso".'],tips:["Cierra el filtro hasta que el sonido quede opaco y ábrelo lentamente: es el gesto clásico del sintetizador."]},practica:{paragraphs:["Bajo: onda de sierra o cuadrada, filtro bastante cerrado, ataque rápido, una octava grave. Pad: dos osciladores desafinados, ataque y liberación lentos, filtro suave. Lead: sierra brillante, algo de glide (portamento) y vibrato."],tips:["Guarda tus sonidos como presets con nombre."]},lectura:{paragraphs:["En la interfaz de un sintetizador: el oscilador tiene forma de onda, afinación (octava, semitono, fino); el filtro, tipo, frecuencia de corte (cutoff) y resonancia; la envolvente, cuatro controles A-D-S-R."],tips:["Sigue el camino de la señal de izquierda a derecha: oscilador → filtro → amplificador."]},oido:{paragraphs:["Con ataque rápido, el sonido aparece de golpe; con ataque lento, entra poco a poco. Escucha y decide."],tips:["Los pads suelen tener ataque lento; los bajos y percusiones, rápido."]}}},"prod-n4-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un LFO (oscilador de baja frecuencia) es una onda muy lenta que no se oye, pero que mueve otro parámetro: el volumen (trémolo), la afinación (vibrato) o el filtro (wah). La modulación da vida y movimiento a sonidos estáticos."],tips:["Sincroniza el LFO al tempo para que el movimiento vaya con la música."]},practica:{paragraphs:["Asigna un LFO al cutoff del filtro de un pad y prueba velocidades de 1/4, 1/8 y 1/16 sincronizadas al tempo. Luego asigna otro LFO suave a la afinación para un vibrato."],tips:["Mueve la profundidad (amount) poco a poco: un poco de modulación basta."]},lectura:{paragraphs:["La matriz de modulación es una tabla que conecta fuentes (LFO, envolventes, velocity, rueda de modulación) con destinos (cutoff, afinación, volumen, paneo), con una cantidad para cada conexión."],tips:['Lee cada fila como "fuente → destino, cantidad".']},oido:{paragraphs:["Un sonido estático no cambia mientras se sostiene; uno modulado se mueve (vibrato, trémolo, filtro). Escucha y decide."],tips:["Sostén la atención en el final de la nota larga."]}}},"prod-n4-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El sampling usa fragmentos de grabaciones (samples) como material para crear: cortar, reordenar, cambiar de tono, estirar o invertir. Es la base del hip hop y de mucha electrónica.","Ojo con los derechos: usar samples de canciones publicadas requiere permiso; usa librerías libres de regalías o graba tus propios sonidos."],tips:["Graba sonidos de tu casa (llaves, vasos, puertas) y conviértelos en percusión."]},practica:{paragraphs:["Corta un sample en partes (slices) y asígnalas a teclas o pads. Estira su duración para ajustarlo al tempo (time-stretch) y cambia su tono por semitonos (pitch shift). Prueba invertirlo."],tips:["Corta siempre en un cruce por cero o con fundidos para evitar clics."]},lectura:{paragraphs:['Muchos loops traen el tempo y la tonalidad en el nombre del archivo (por ejemplo "guitarra_95bpm_Am.wav"). El DAW puede detectar el tempo y ajustarlo al proyecto.'],tips:["Elige loops en la tonalidad de tu canción o en una relativa."]},oido:{paragraphs:["Escucha una pista y detecta cuándo se repite un loop y cuántos compases dura."],tips:["Cuenta los compases desde que empieza hasta que vuelve a empezar."]}}},"prod-n4-l09":{status:"borrador",generated:!0,sections:{teoria:e.s048,practica:{paragraphs:["Cambiar el modo cambia el color de una progresión. Por ejemplo, de Do mayor (C – F – G) a Do menor (Cm – Fm – Gm o G) o a Do mixolidio (C – B♭ – F). El préstamo modal toma acordes del modo paralelo: en Do mayor, usar Fm o A♭ le da un toque melancólico."],tips:["Prueba C – F – Fm – C: el Fm es un préstamo muy usado en el pop."]},lectura:e.s049,oido:e.s050}},"prod-n4-l10":{status:"borrador",generated:!0,sections:{teoria:e.s079,practica:{paragraphs:["Programa en el piano roll: Cmaj7 (Do–Mi–Sol–Si), Am7 (La–Do–Mi–Sol), Dm9 (Re–Fa–La–Do–Mi) y G7 (Sol–Si–Re–Fa). Repártelos en un registro medio y usa inversiones para que se muevan poco."],tips:["Los acordes con novena suenan muy bien en neo-soul y lo-fi."]},lectura:e.s003,oido:e.s080}},"prod-n4-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Además de corregir, los efectos crean: sidechain (bombeo), filtros que abren y cierran, delays rítmicos, reverbs invertidas, cortes de volumen (stutter) y automatizaciones que cambian el sonido en las transiciones."],tips:["Usa los efectos creativos en momentos concretos para que sorprendan."]},practica:{paragraphs:["Aplica sidechain al bajo y al pad con el bombo para un efecto de bombeo. Automatiza un filtro paso alto que suba durante los 4 compases antes del coro y que se abra de golpe al llegar."],tips:["Esa subida de filtro (build-up) es típica de la electrónica y el pop."]},lectura:e.s195,oido:{paragraphs:['Con sidechain, el bajo o el pad "respiran" bajando de volumen en cada golpe de bombo; sin sidechain, suenan constantes. Escucha y decide.'],tips:["Fíjate en el colchón: si late con el bombo, hay sidechain."]}}},"prod-n4-l12":{status:"borrador",generated:!0,sections:{teoria:e.s067,practica:{paragraphs:["Elige una canción corta y recrea 8 compases: tempo, batería, bajo, acordes y sonidos principales. No se trata de copiar para publicar, sino de aprender cómo está hecha."],tips:["Compara tu versión con la original al mismo volumen."]},lectura:e.s068,oido:e.s069}},"prod-n5-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Antes de mezclar, ordena la sesión: nombra y colorea pistas, agrúpalas por tipo, elimina pistas vacías, crea buses y marcadores de sección. Una sesión ordenada ahorra tiempo y errores."],tips:["Sigue siempre el mismo orden: batería, bajo, guitarras, teclados, voces, efectos."]},practica:{paragraphs:["Ordena una sesión completa: nombres claros, colores por grupo, buses, marcadores de sección y niveles iniciales razonables (picos alrededor de −10 dBFS en cada pista)."],tips:["Guarda una copia antes de empezar a mezclar."]},lectura:{paragraphs:["En una sesión ordenada se reconoce rápido qué es cada pista por su nombre y color, a qué bus va y dónde empieza cada sección."],tips:["Compara una sesión desordenada con una ordenada: ¿cuál es más fácil de leer?"]},oido:{paragraphs:["Una mezcla ordenada tiene cada instrumento en su lugar y se entiende; una caótica suena amontonada. Escucha y decide."],tips:["Fíjate si puedes seguir la voz y el bajo sin esfuerzo."]}}},"prod-n5-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La ecualización correctiva quita problemas: graves innecesarios (filtro paso alto), resonancias molestas, zonas que chocan con otros instrumentos. La creativa realza el carácter: más brillo, más cuerpo o un sonido telefónico.","Regla general: recorta con filtros estrechos y realza con filtros amplios."],tips:["Primero recorta, luego realza."]},practica:{paragraphs:["Encuentra una resonancia: realza una banda estrecha, recórrela hasta que suene peor y luego recórtala. Resuelve un conflicto: si guitarra y voz chocan en 2–3 kHz, recorta un poco esa zona en la guitarra."],tips:["Ecualiza escuchando la mezcla completa, no la pista sola."]},lectura:{paragraphs:["La curva del ecualizador muestra frecuencia (horizontal) y ganancia (vertical). Cada punto es una banda con frecuencia, ganancia y ancho (Q)."],tips:["Q alto = banda estrecha; Q bajo = banda amplia."]},oido:{paragraphs:["Cuando dos instrumentos ocupan la misma frecuencia, se enmascaran y ninguno se oye claro. Escucha y decide si hay choque."],tips:["Silencia uno de los dos: si el otro de repente se aclara, había choque."]}}},"prod-n5-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El compresor reduce la diferencia entre partes fuertes y suaves. Parámetros: umbral (desde dónde actúa), ratio (cuánto comprime), ataque (qué tan rápido actúa), relajación (release: qué tan rápido suelta) y ganancia de salida.","La compresión paralela mezcla la señal original con una copia muy comprimida: da fuerza sin perder dinámica."],tips:["Un ataque lento deja pasar el golpe inicial y da más pegada."]},practica:{paragraphs:["Comprime una batería con ataque rápido y luego lento y escucha la diferencia en la pegada. Crea un bus paralelo muy comprimido y mézclalo poco a poco con la batería original."],tips:['Ajusta la relajación para que el compresor "respire" con el tempo.']},lectura:{paragraphs:["El medidor de reducción de ganancia (GR) muestra cuántos dB está bajando el compresor. 2–6 dB es una compresión moderada."],tips:["Si la reducción nunca vuelve a 0, la relajación es demasiado lenta o el umbral muy bajo."]},oido:{paragraphs:["Con ataque rápido, el golpe inicial se suaviza; con ataque lento, el golpe pasa y se oye más pegada. Escucha y decide."],tips:["Fíjate en el inicio de cada golpe de batería."]}}},"prod-n5-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La reverb y el delay crean profundidad: un instrumento con poca reverb parece cercano; con mucha, lejano. Se usan en buses (envíos) para compartir el mismo espacio entre varias pistas."],tips:["Usa un predelay de 20–60 ms en la voz para que tenga espacio sin alejarse."]},practica:{paragraphs:["Organiza la mezcla en planos: al frente (voz, elemento principal: más volumen, menos reverb, más brillo), en medio (guitarras, teclados) y atrás (colchones, coros: menos volumen, más reverb, menos agudos)."],tips:["Quitar agudos aleja un sonido; agregarlos lo acerca."]},lectura:{paragraphs:["Un envío (send) manda una copia de la señal de una pista a un bus de efecto; el retorno es ese bus, con el efecto al 100% (wet). La perilla de envío decide cuánta señal va al efecto."],tips:["Pon los efectos de reverb y delay en retornos, no directamente en cada pista."]},oido:{paragraphs:["Escucha un sonido y decide si suena cerca o lejos en la mezcla."],tips:["Fíjate en el volumen, la reverb y el brillo."]}}},"prod-n5-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['La saturación agrega armónicos que dan calidez, presencia y "pegada". Emula cinta (suave y cálida), válvulas (rica y armónica) o distorsión suave. Un poco ayuda a que un sonido se escuche mejor en bocinas pequeñas.'],tips:["Usa la saturación como la sal: poquita hace mucha diferencia."]},practica:{paragraphs:["Aplica a un bajo un plugin de cinta, luego de válvula y luego una distorsión suave, ajustando el drive bajo. Compara con el sonido original al mismo volumen."],tips:["Iguala el volumen al comparar: lo más fuerte siempre parece mejor."]},lectura:{paragraphs:["Un plugin de saturación suele tener drive (cuánto se satura), tipo (cinta, válvula…), tono y mezcla (mix) para combinar con la señal original."],tips:["El control mix permite saturar en paralelo."]},oido:{paragraphs:["El sonido limpio es neutro; el saturado, más cálido, denso o áspero. Escucha y decide."],tips:["Fíjate en el brillo y la densidad del sonido."]}}},"prod-n5-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['La voz principal debe estar al frente y entenderse siempre. Cadena típica: limpieza (edición y paso alto), ecualización, compresión (a veces dos compresores suaves), de-esser (para las "s"), saturación ligera y envíos a reverb y delay. Coros y dobles van más bajos, paneados y con más reverb.'],tips:["Automatiza el volumen de la voz palabra por palabra si hace falta."]},practica:{paragraphs:["Mezcla la voz principal al centro y al frente; los dobles a los lados, más bajos; los coros paneados, con ecualización más ligera y más reverb."],tips:["Los dobles no deben competir con la voz principal: bájalos hasta que apenas se noten."]},lectura:{paragraphs:["La cadena de efectos se lee de arriba hacia abajo en los insertos de la pista: el orden importa (por ejemplo, ecualizar antes o después de comprimir cambia el resultado)."],tips:["Anota tu cadena de voz para repetirla en otras canciones."]},oido:{paragraphs:["Escucha una mezcla y decide si la voz está al frente o escondida."],tips:["Si te cuesta entender la letra, la voz está escondida."]}}},"prod-n5-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El bombo y el bajo comparten los graves y pueden chocar. Soluciones: decidir quién ocupa la frecuencia más grave (por ejemplo, bajo en 60–80 Hz y bombo en 50–60 Hz o al revés), ecualizar para que no se pisen y usar sidechain para que el bajo baje cuando suena el bombo."],tips:["Revisa los graves en audífonos y en bocinas con buen grave."]},practica:{paragraphs:["Recorta un poco el bajo en la frecuencia principal del bombo, realza el ataque del bombo (2–4 kHz) y aplica un sidechain suave al bajo. Escucha ambos juntos."],tips:["Haz que el bajo siga el ritmo del bombo: suenan como un solo instrumento."]},lectura:{paragraphs:["En el analizador, observa la zona de 20–200 Hz: los picos muestran dónde está la energía del bombo y del bajo. Si ambos tienen el pico en la misma frecuencia, probablemente chocan."],tips:['Usa el modo de "solo graves" del analizador si lo tiene.']},oido:{paragraphs:["Escucha y decide si el bajo y el bombo están equilibrados o si uno tapa al otro."],tips:["Ambos deben oírse claramente sin que el grave retumbe."]}}},"prod-n5-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El estéreo tiene dos canales (izquierdo y derecho) que crean amplitud. En mono, ambos se suman: algunos efectos estéreo pueden cancelarse y desaparecer. Muchas bocinas (celulares, bocinas Bluetooth) reproducen en mono.","Lo grave (bombo, bajo) y la voz principal suelen ir al centro."],tips:["Revisa siempre tu mezcla en mono."]},practica:{paragraphs:["Activa el modo mono en el master y escucha: ¿desaparece algún instrumento?, ¿se pierde la reverb? Si algo se cancela, reduce el ensanchador estéreo o cambia el efecto."],tips:["Una mezcla que suena bien en mono suena bien en todos lados."]},lectura:{paragraphs:["El medidor de correlación va de −1 a +1: +1 significa que ambos canales son iguales (mono); 0, muy distintos; valores negativos indican problemas de fase que se cancelarán en mono."],tips:["Mantén la correlación mayormente en valores positivos."]},oido:{paragraphs:["Escucha y decide si la mezcla suena amplia (estéreo) o centrada (mono)."],tips:["Usa audífonos para notar mejor la amplitud."]}}},"prod-n5-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La automatización cambia parámetros durante la canción: volumen, paneo, envíos, filtros. Sirve para contar la historia: subir la voz en el coro, abrir la reverb en el final, bajar las guitarras en el verso."],tips:["La automatización es lo que hace que una mezcla se sienta viva."]},practica:{paragraphs:["Automatiza: el volumen de la voz en frases que se pierden, un aumento de reverb en la última palabra del coro y un filtro que se abre en la intro."],tips:["Escucha toda la canción después de automatizar para revisar la transición entre secciones."]},lectura:e.s195,oido:{paragraphs:["Escucha y decide si un instrumento sube o baja de volumen durante la canción."],tips:["Sigue un solo instrumento de principio a fin."]}}},"prod-n5-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La masterización es el último paso: prepara la mezcla para publicarse. Ajusta el balance tonal (ecualización suave), controla la dinámica (compresión suave), sube el volumen con un limitador sin distorsionar y revisa que suene bien en todos los sistemas.","Para streaming, un volumen integrado alrededor de −14 LUFS y picos verdaderos por debajo de −1 dBTP es una referencia común."],tips:["Masteriza otro día, con oídos frescos."]},practica:{paragraphs:["En el bus master: ecualizador suave (cambios de 1–2 dB), compresor con ratio bajo (1.5–2:1) y 1–2 dB de reducción, y al final un limitador con techo en −1 dBTP. Compara con la mezcla original al mismo volumen."],tips:["Si el limitador reduce más de 4–6 dB, la mezcla probablemente necesita trabajo antes."]},lectura:e.s196,oido:e.s197}},"prod-n5-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["WAV (sin compresión, 24 bits / 44.1 o 48 kHz) es el formato de entrega para distribución. MP3 y AAC son formatos comprimidos para compartir. Para video se usa normalmente 48 kHz; para CD, 16 bits / 44.1 kHz."],tips:["Guarda siempre una copia del master en WAV de alta calidad."]},practica:{paragraphs:["Exporta tu master en tres versiones: WAV 24 bits / 44.1 kHz para distribución digital, WAV 24 bits / 48 kHz para video y WAV 16 bits / 44.1 kHz con dither para CD. Nombra los archivos claramente."],tips:["Aplica dither solo al reducir a 16 bits."]},lectura:e.s198,oido:e.s199}},"prod-n5-l12":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Al mezclar para otra persona, entiende su visión: pide referencias, pregunta qué quiere destacar y acuerda el número de revisiones y la fecha de entrega. Entrega mezclas en formatos claros y con nombres de versión."],tips:["Escribe un pequeño acuerdo con alcance, revisiones, fecha y precio."]},practica:{paragraphs:["Envía la mezcla con un mensaje claro, recibe las notas con marcas de tiempo, aplica los cambios y envía una nueva versión con el número correspondiente (v2, v3…)."],tips:["Agradece las notas aunque no estés de acuerdo; luego explica tus razones."]},lectura:e.s200,oido:e.s201}},"prod-n6-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La preproducción define el proyecto antes de grabar: concepto, estilo, referencias, número de canciones, tempos, tonalidades, instrumentación, calendario y presupuesto. Ahorra tiempo y dinero en el estudio."],tips:["Haz una carpeta con referencias para cada canción."]},practica:{paragraphs:["Escribe en una página: el estilo, 3 canciones de referencia, la instrumentación principal, el tipo de voz y el ambiente (íntimo, energético, oscuro…)."],tips:["Revisa esta página cada vez que dudes en una decisión."]},lectura:{paragraphs:["Una hoja de preproducción resume cada canción: título, tempo, tonalidad, estructura, instrumentos, referencias y estado (por componer, por grabar, por mezclar)."],tips:["Mantenla actualizada durante todo el proyecto."]},oido:{paragraphs:["Escucha una referencia e identifica sus rasgos: instrumentos, tempo, ambiente, voz y mezcla."],tips:["Haz una lista de lo que quieres tomar de esa referencia."]}}},"prod-n6-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Compón o termina las canciones del proyecto. Empieza por la idea central (gancho, progresión o letra) y desarrolla la estructura. Graba maquetas sencillas de cada una."],tips:["No te detengas a producir mientras compones: primero termina la canción."]},practica:{paragraphs:["Graba maquetas de tus canciones: voz guía, acordes y un ritmo básico. Define tempo y tonalidad finales."],tips:["Una maqueta sirve para decidir el arreglo, no para sonar perfecta."]},lectura:e.s114,oido:e.s115}},"prod-n6-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Graba las voces e instrumentos de tu proyecto siguiendo un plan: primero las bases (batería, bajo, guitarras o teclados de ritmo), luego los elementos principales y al final las voces y los detalles."],tips:["Anota la configuración de micrófonos y ganancias de cada sesión."]},practica:{paragraphs:["Graba las pistas de tu proyecto según tu plan. Revisa afinación, tiempo y ruido en cada toma, y nombra las pistas de forma clara."],tips:["Haz respaldo de tus archivos al final de cada sesión."]},lectura:e.s100,oido:e.s101}},"prod-n6-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Completa el arreglo y el diseño sonoro: agrega capas, efectos creativos, transiciones y detalles que den identidad a cada canción."],tips:["Quita lo que no aporte: menos es más."]},practica:{paragraphs:["Revisa el arreglo de cada canción por secciones: entradas, salidas, transiciones y momentos de impacto. Diseña los sonidos finales (sintetizadores, efectos) y fija el arreglo antes de mezclar."],tips:["Escucha la canción completa sin detenerte para sentir su flujo."]},lectura:e.s192,oido:{paragraphs:["Escucha una canción y señala en qué momento entra y sale cada instrumento."],tips:["Anota los tiempos con el reloj del reproductor."]}}},"prod-n6-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Mezcla las canciones de tu proyecto con una base común (mismos buses, reverbs y referencias) para que suenen como un conjunto coherente."],tips:["Mezcla primero la canción más representativa y úsala como modelo."]},practica:{paragraphs:["Mezcla tus canciones paso a paso: niveles y paneo, ecualización, compresión, espacio, automatización. Compara con tus referencias."],tips:["Haz pausas cada 45–60 minutos."]},lectura:{paragraphs:["Revisa tu sesión de mezcla: buses, envíos, plugins y automatización. Asegúrate de que todo esté nombrado y ordenado."],tips:["Exporta un resumen de tu cadena de master para usarla en todas las canciones."]},oido:e.s201}},"prod-n6-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Masteriza las canciones del proyecto de forma coherente: volumen y tono similares entre canciones, espacios entre pistas y orden final."],tips:["Escucha el proyecto completo en orden después de masterizar."]},practica:{paragraphs:["Masteriza cada canción comparando con tus referencias al mismo volumen. Ajusta el balance tonal y el volumen final para que el proyecto suene parejo."],tips:['Las canciones del mismo proyecto deben sentirse del mismo "mundo".']},lectura:e.s196,oido:e.s197}},"prod-n6-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Comparte tu proyecto con el profe Luis o con personas de confianza y pide retroalimentación concreta. Escucha sin defenderte y después decide qué cambiar."],tips:['Pregunta: "¿qué fue lo primero que notaste?".']},practica:{paragraphs:["Aplica las correcciones de la retroalimentación: ajusta mezcla, master o arreglos según lo necesario. Exporta las versiones finales."],tips:['Pon un límite de revisiones: un proyecto nunca está "perfecto".']},lectura:e.s200,oido:{paragraphs:["Escucha tu mezcla buscando errores: clics, ruidos, cortes, cambios bruscos de volumen o instrumentos que desaparecen."],tips:["Escucha con audífonos a volumen moderado para detectar detalles."]}}},"prod-n6-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En vivo, la computadora puede reproducir pistas de acompañamiento (backing tracks), secuencias, clic para los músicos y efectos. Se usa un DAW pensado para vivo (como Ableton Live) o un reproductor de pistas.","Lo importante es la estabilidad: computadora dedicada, sin notificaciones, con respaldo."],tips:["Ten siempre un plan B si la computadora falla."]},practica:{paragraphs:["Prepara una sesión de vivo: cada canción con su pista de acompañamiento, el clic en un canal separado (solo para audífonos) y marcadores de sección. Revisa niveles y transiciones."],tips:["Ensaya el show completo con la sesión, de principio a fin."]},lectura:e.s124,oido:{paragraphs:["En vivo, los músicos escuchan el clic y la pista por audífonos o in-ears. Escucha y decide si la banda va a tiempo con el clic."],tips:["Si te adelantas, relaja; si te atrasas, escucha más el clic que a los demás."]}}},"prod-n6-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Equipo básico para vivo: computadora, interfaz con salidas separadas (público y monitoreo), controlador MIDI para lanzar escenas, cables de repuesto y sistema de monitoreo in-ear. Prueba todo antes del concierto."],tips:["Desactiva el wifi, las actualizaciones y las notificaciones durante el show."]},practica:e.s126,lectura:e.s127,oido:e.s128}},"prod-n6-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Para publicar en plataformas (Spotify, Apple Music, YouTube Music…) se usa una distribuidora digital. Necesitas el master en WAV, la portada (normalmente 3000×3000 px), los metadatos (título, artista, compositores, género, fecha) y, si los tienes, los códigos ISRC."],tips:["Programa el lanzamiento con varias semanas de anticipación."]},practica:{paragraphs:["Prepara tu lanzamiento: master en WAV, portada cuadrada de 3000×3000 px sin textos pequeños, metadatos completos y créditos correctos. Elige una distribuidora y revisa sus requisitos."],tips:["Revisa la ortografía de los títulos y nombres antes de enviar: cambiarlos después es difícil."]},lectura:e.s198,oido:e.s199}},"prod-n6-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Al publicar, protege tu trabajo: registra tus obras (en México, ante el INDAUTOR) y afíliate a una sociedad de gestión (como la SACM) para cobrar regalías. Planea la promoción: redes sociales, video, listas de reproducción y presentaciones."],tips:["Guarda todas tus maquetas y archivos con fechas: también son prueba de autoría."]},practica:{paragraphs:["Escribe un plan de lanzamiento de 6 semanas: semana 1 registro y distribución, semanas 2–5 contenido en redes (adelantos, detrás de cámaras), semana 6 lanzamiento y presentación. Incluye el registro de tus obras."],tips:["Un calendario sencillo y constante funciona mejor que publicar todo de golpe."]},lectura:{paragraphs:["Un plan de lanzamiento muestra en una línea de tiempo las tareas, fechas y responsables: entrega a la distribuidora, contenido, prensa, fecha de salida."],tips:["Marca las fechas límite de la distribuidora (suelen pedir 2–4 semanas antes)."]},oido:{paragraphs:["El gancho es la parte más pegajosa de una canción: una frase, una melodía o un sonido que recuerdas. Escucha y señala el gancho."],tips:["Si lo tarareas al día siguiente, ese es el gancho."]}}},"prod-n6-l12":{status:"borrador",generated:!0,sections:{teoria:e.s129,practica:{paragraphs:["Repasa las técnicas principales del curso en el DAW, del nivel 1 al 6, con metrónomo. Detecta las que ya dominas y las que necesitas seguir practicando.","Organiza una rutina de mantenimiento para después del curso: técnica, repertorio y creación."],tips:["Grábate tocando una pieza de cada nivel: verás todo lo que has avanzado."]},lectura:e.s130,oido:e.s131}}},t={"prod-n2-l01":s(a("Arreglar es decidir qué instrumento hace qué y en qué momento. Cada capa tiene una función: ritmo (batería, percusión), base armónica (bajo, acordes), melodía (voz o instrumento principal) y relleno o color (pads, contramelodías, efectos).","Una buena producción no tiene todo sonando todo el tiempo: deja entrar y salir capas para que cada sección se sienta distinta.","> Si dos instrumentos hacen lo mismo en el mismo registro, uno sobra o tiene que cambiar."),a("Toma la idea de 8 compases que hiciste en el Nivel 1 (batería, bajo, acordes y melodía). Duplícala a 32 compases y decide qué capa entra en cada parte: introducción solo con acordes, verso con batería y bajo, coro con todo y una capa extra.","Silencia y activa pistas para escuchar cómo cambia la energía.","> Prueba quitar algo en lugar de agregar: a veces es la mejor idea."),a("Un arreglo por secciones se lee en la línea de tiempo con marcadores (Intro, Verso, Coro…) y bloques de color por pista. De un vistazo ves qué suena en cada parte.","Pinta tus regiones con un color por función: rojo ritmo, azul armonía, verde melodía, amarillo color.","> Nombra cada pista con su función: «Bajo – base», «Pad – color»."),a("Escucha una canción que te guste y anota en qué segundo entra o sale cada instrumento. Fíjate en lo que cambia justo antes del coro.","> Lo que sale también se nota: el silencio de un instrumento crea expectativa.")),"prod-n2-l02":s(a("Grabar por capas es construir la canción pista por pista sobre el metrónomo o una guía. Una toma doble es grabar la misma parte dos veces, idéntica, para que suene más grande y ancha.","Las tomas dobles funcionan muy bien en coros de voz y guitarras rítmicas; en la voz principal de los versos se suele dejar una sola toma.","> La toma doble tiene que ser igual en ritmo y fraseo; si no, suena desordenado."),a("Graba una parte (voz o instrumento) con metrónomo. Después graba la misma parte en otra pista, lo más parecida posible. Panea una toma un poco a la izquierda y otra a la derecha y compara con una sola.","Usa audífonos cerrados para que el metrónomo no se cuele en el micrófono.","> Graba 3 o 4 tomas de cada parte: luego eliges la mejor."),a("Una hoja de sesión resume la canción para grabar: tempo, tono, compás, forma por secciones con número de compases y qué se graba en cada pista.","Ejemplo: 92 BPM · La menor · 4/4 · Intro 4 · Verso 8 · Coro 8 · Verso 8 · Coro 8 · Final 4.","> Tenla abierta junto al DAW mientras grabas."),a("Escucha dos tomas de la misma voz y di cuál está más afinada y a tiempo. Escucha también cómo suena una sola toma contra una doble.","> Con audífonos, la toma doble se siente «más ancha».")),"prod-n2-l03":s(a("El balance es el volumen de cada pista respecto a las demás. Es el primer paso de la mezcla y el más importante: con un buen balance, la canción ya funciona.","Se trabaja con los faders del mezclador. Deja margen: que el bus master quede con picos alrededor de −6 dBFS, sin llegar a 0.","> Mezcla a volumen bajo-medio: a volumen alto todo parece bien."),a("Baja todos los faders. Sube primero el elemento principal (casi siempre la voz o la melodía), luego el bombo y el bajo, después la tarola y por último acordes y colores. Cada vez, pregúntate si la voz se sigue entendiendo.","Haz el balance con la sección más fuerte de la canción (normalmente el coro).","> Cierra los ojos al mover un fader: decide con el oído, no con la pantalla."),a("El fader indica cuánto suena una pista en dB: 0 dB es sin cambio, −6 dB es más bajo. El medidor muestra el nivel real de la señal; si llega a rojo en el master, está saturando.","> Un fader en −10 no es «malo»: lo importante es cómo suena junto a los demás."),a("Escucha la mezcla y nombra el instrumento que suena más fuerte y el que casi no se oye. Compara con una canción de referencia del mismo estilo.","> Escucha también en el celular: ahí se nota si el bajo desaparece.")),"prod-n2-l04":s(a("El paneo coloca cada sonido de izquierda a derecha en el espacio estéreo. Ayuda a que los instrumentos no se encimen y a que la mezcla se sienta amplia.","Lo más común: bombo, tarola, bajo y voz principal al centro; guitarras, teclados, coros y percusiones repartidos a los lados.","> El centro es para lo más importante; los lados, para lo que acompaña."),a("Ubica cada pista: deja al centro la base y la voz, abre las tomas dobles (por ejemplo 70 % izquierda y 70 % derecha) y coloca los colores en lugares que no compitan.","Revisa la mezcla en mono: si algo desaparece, el paneo o las fases tienen un problema.","> Equilibra: si algo fuerte va a la izquierda, pon algo similar a la derecha."),a("El paneo se lee en la perilla de cada canal: C (centro), L50 (mitad a la izquierda), R100 (todo a la derecha). Algunos DAW usan valores de −64 a +63.","> Escribe en tu hoja de sesión el paneo de cada pista."),a("Con audífonos, escucha una mezcla y di dónde está cada instrumento: izquierda, centro o derecha.","> Tápate un oído y luego el otro para comprobar.")),"prod-n2-l05":s(a("El ecualizador (EQ) sube o baja frecuencias: graves (20–250 Hz), medios (250 Hz–4 kHz) y agudos (4–20 kHz). Sirve para limpiar lo que estorba y dar claridad a lo importante.","Regla útil: primero quita (recortes) y después agrega con cuidado. Un filtro pasa-altos en pistas que no necesitan graves (voz, guitarras, teclados) deja espacio para el bombo y el bajo.","> Ecualiza escuchando toda la mezcla, no la pista sola."),a("Pon un filtro pasa-altos en la voz alrededor de 80–100 Hz. Busca frecuencias molestas con una banda estrecha subida y barriendo; cuando suene feo, bájala 2–4 dB.","Después, si hace falta, sube un poco los agudos (alrededor de 8–10 kHz) para dar brillo.","> Cambios pequeños (1–3 dB) suelen ser suficientes."),a("La curva del ecualizador muestra frecuencias de izquierda (graves) a derecha (agudos) y ganancia arriba (subir) o abajo (bajar). La Q es qué tan ancha es cada banda.","> Una curva muy «montañosa» casi siempre es demasiado."),a("Escucha un sonido y di si le cambiaron graves, medios o agudos. Los graves dan cuerpo, los medios presencia y los agudos brillo y aire.","> Practica con el mismo audio en tres versiones: más graves, más medios y más agudos.")),"prod-n2-l06":s(a("La compresión reduce la diferencia entre las partes fuertes y suaves de una pista. Hace que la voz o el bajo se escuchen parejos y presentes.","Controles principales: umbral (desde qué nivel actúa), ratio (cuánto reduce), ataque (qué tan rápido actúa), liberación (qué tan rápido suelta) y ganancia de salida (para recuperar volumen).","> Comprimir no es hacer más fuerte: es hacer más parejo."),a("En la voz, empieza con ratio 3:1, ataque medio (10–20 ms) y liberación media (80–120 ms). Baja el umbral hasta que el medidor de reducción marque 3–6 dB en las partes fuertes.","En el bajo, ratio 4:1 con ataque un poco más lento para que se escuche el golpe de cada nota.","> Compara con el compresor apagado y al mismo volumen: a veces solo parece mejor porque suena más fuerte."),a("El medidor de reducción de ganancia (GR) muestra cuántos dB está bajando el compresor. Si se queda fijo y muy abajo todo el tiempo, estás comprimiendo de más.","> 3 a 6 dB de reducción es un buen punto de partida."),a("Escucha una pista con y sin compresión. La comprimida suena más pareja y cercana; la que no tiene compresión tiene más diferencia entre partes suaves y fuertes.","> Pon atención a las palabras finales de cada frase: con compresión no se pierden.")),"prod-n2-l07":s(a("La reverberación (reverb) simula un espacio: cuarto, sala o iglesia. El delay es un eco que repite el sonido después de un tiempo. Los dos dan profundidad y ambiente.","Se usan casi siempre en un canal de efectos (envío o «send»): varias pistas comparten la misma reverb y suenan dentro del mismo espacio.","> Poca reverb acerca el sonido; mucha lo aleja."),a("Crea un canal de efectos con una reverb de sala y otro con un delay a tempo (por ejemplo, de negra o corchea con puntillo). Envía la voz a los dos en poca cantidad.","Ecualiza la reverb con un pasa-altos (unos 200–300 Hz) para que no ensucie los graves.","> Si notas la reverb, quizá está un poco alta; si al quitarla la extrañas, está bien."),a("En el mezclador, el envío (send) es una perilla en cada canal que manda una copia de la señal al canal de efectos (retorno). El retorno se mezcla como cualquier otra pista.","> Pon el efecto al 100 % «wet» en el canal de retorno."),a("Escucha una voz seca, con delay y con reverb. El delay se escucha como repeticiones claras; la reverb, como una cola de sonido que se va apagando.","> En el delay puedes contar las repeticiones; en la reverb, no.")),"prod-n2-l08":s(a("La automatización graba movimientos de volumen, paneo o efectos a lo largo de la canción. Así la mezcla cambia sola: la voz sube en una palabra, el delay aparece al final de una frase, el filtro se abre antes del coro.","Hace que la mezcla se sienta viva en lugar de estática.","> Automatiza al final, cuando el balance ya está bien."),a("Automatiza el volumen de la voz para que las palabras que se pierden suban 1–2 dB. Después automatiza el envío del delay para que solo aparezca en la última palabra de cada frase.","Como reto, automatiza un filtro pasa-bajos en la batería durante la introducción y ábrelo justo cuando entra el verso.","> Escucha cada automatización en contexto: no debe notarse como «truco»."),a("La automatización se ve como una línea con puntos sobre la pista. Arriba es más, abajo es menos. Cada punto es un cambio en un momento exacto.","> Usa pocos puntos: curvas suaves suenan más naturales."),a("Escucha una mezcla y levanta la mano cada vez que sientas que un instrumento sube o baja de volumen.","> Los cambios más comunes ocurren en la entrada del coro y en el final.")),"prod-n2-l09":s(a("Un sintetizador crea sonidos desde cero. Su camino básico es: oscilador (la onda: senoidal, triangular, cuadrada o diente de sierra) → filtro (quita agudos o graves) → amplificador con envolvente (cómo empieza y termina el sonido).","La envolvente ADSR controla ataque (cuánto tarda en sonar), decaimiento, sostenimiento (nivel mientras mantienes la tecla) y liberación (cuánto tarda en apagarse).","> Diente de sierra = brillante; senoidal = suave y redonda."),a("Diseña tres sonidos con el sintetizador de tu DAW: un bajo (onda cuadrada, filtro cerrado, ataque rápido), un pad (diente de sierra, ataque y liberación lentos) y un lead (diente de sierra, filtro abierto, un poco de glide).","Guarda cada sonido con un nombre claro para usarlo en tu producción.","> Cambia un solo control a la vez para entender qué hace."),a("Lee los controles en orden de izquierda a derecha: OSC (oscilador), FILTER (corte o cutoff y resonancia), AMP o ENV (ADSR) y LFO (movimiento automático de algún parámetro).","> Si un sonido no suena, revisa primero el volumen del oscilador y el corte del filtro."),a("Escucha sonidos y decide: ¿la onda es suave o brillante?, ¿el filtro está abierto o cerrado?, ¿el ataque es rápido (golpe) o lento (entra poco a poco)?","> Imita con la voz el sonido: «uuu» (filtro cerrado) contra «iii» (filtro abierto).")),"prod-n2-l10":s(a("Una muestra (sample) es un fragmento de audio grabado: un golpe de batería, una frase, un acorde. Un loop es una muestra que se repite en ciclo, normalmente de 1, 2 o 4 compases.","Usa muestras libres de derechos o de paquetes con licencia, y respeta las condiciones de uso. No uses fragmentos de canciones de otros artistas sin permiso.","> Lee la licencia del paquete antes de publicar tu canción."),a("Importa un loop de batería y ajústalo al tempo de tu proyecto. Córtalo en partes (bombo, tarola, platillos) y reordénalas para crear un patrón nuevo.","Después corta un acorde o frase de un loop melódico y tócalo como instrumento en un muestreador.","> Corta siempre en cruces por cero o con pequeños fundidos para evitar clics."),a("Los loops suelen indicar su tempo y su tono en el nombre: «Drums_92bpm» o «Keys_Am_120bpm». Si el tempo no coincide, el DAW lo estira (time-stretch); si el tono no coincide, hay que transponerlo.","> Organiza tus muestras en carpetas por tipo y tempo."),a("Escucha una canción y detecta qué parte se repite igual (un loop) y qué parte cambia. Cuenta cuántos compases dura el ciclo.","> Muchos géneros se construyen sobre un loop de 2 o 4 compases.")),"prod-n2-l11":s(a("La masterización es el último paso: se trabaja la mezcla final completa para que suene equilibrada, con buen volumen y lista para publicarse.","Herramientas básicas: un ecualizador suave, un compresor ligero y un limitador al final que evita que la señal pase de un techo (por ejemplo −1 dBTP).","> Si la mezcla tiene un problema, arréglalo en la mezcla, no en el máster."),a("Exporta tu mezcla con margen (picos alrededor de −6 dBFS) a WAV. Ábrela en un proyecto nuevo, agrega un limitador con techo de −1 dB y sube la ganancia poco a poco hasta un volumen parecido al de tu referencia, sin que se aplaste.","Compara siempre al mismo volumen percibido con la versión sin masterizar.","> Más volumen no es más calidad: busca que siga respirando."),a("El medidor de volumen integrado (LUFS) indica el volumen promedio de toda la canción. Muchas plataformas normalizan alrededor de −14 LUFS; el medidor de pico real (dBTP) evita saturaciones al convertir a otros formatos.","> Anota los LUFS de tu canción y de tu referencia."),a("Compara tu máster con una canción de referencia del mismo estilo y al mismo volumen. ¿Tu canción tiene más o menos graves? ¿Más o menos brillo? ¿La voz está igual de presente?","> Haz la comparación en audífonos, bocinas y celular.")),"prod-n2-l12":s(a("Para publicar tu música necesitas el máster final en WAV (16 o 24 bits, 44.1 kHz), una portada cuadrada (por ejemplo 3000 × 3000 px), el título, los créditos y una distribuidora digital que la envíe a las plataformas.","Guarda también una versión en MP3 de buena calidad para compartir y las pistas o «stems» por si quieres hacer cambios o presentarla en vivo.","> Respeta los derechos: si usaste muestras, que su licencia permita publicar."),a("Exporta tu producción terminada (2 minutos o más) en WAV y MP3. Prepara una ficha con título, tempo, tono, instrumentos y qué hiciste tú en cada parte. Preséntala en clase.","> Escúchala completa al día siguiente antes de darla por terminada: el oído descansado ve detalles nuevos."),a("Repaso de lectura del nivel: arreglo por secciones, hoja de sesión, faders y medidores, paneo, curvas de EQ, compresor y reducción de ganancia, envíos y retornos, automatización, controles del sintetizador, tempo y tono de loops y medidor de LUFS.","Abre tu proyecto y explica en voz alta qué hace cada pista, cada efecto y cada automatización.","> Si algo no lo puedes explicar, pregúntalo en clase."),a("Escucha crítica de tu propia mezcla: anota tres cosas que te gustan y tres que mejorarías (balance, claridad, espacio, volumen).","> Escúchala en tres lugares distintos antes de decidir."))},d={...n,...i,...t};export{d as CONTENT};
